    fun project(lon: Double, lat: Double, width: Float = 2000f, height: Float = 2000f): Pair<Float, Float> {
        val x = (((lon - MIN_LON) / (MAX_LON - MIN_LON)) * width).toFloat().coerceIn(20f, width - 20f)
